import type { Command } from "foldkit";
import { Ui } from "foldkit";

export const { Model } = Ui.Switch;
export type Model = Ui.Switch.Model;

export const { SetChecked } = Ui.Switch;
export const { Message } = Ui.Switch;
export type Toggled = Ui.Switch.Toggled;
export type SetChecked = Ui.Switch.SetChecked;
export type Message = Ui.Switch.Message;

export const { ToggledChecked } = Ui.Switch;
export const { OutMessage } = Ui.Switch;
export type ToggledChecked = Ui.Switch.ToggledChecked;
export type OutMessage = Ui.Switch.OutMessage;

export type InitConfig = Ui.Switch.InitConfig;
export type Commands = readonly Command.Command<Message>[];
export type InitReturn = readonly [Model, Commands];
export type UpdateReturn = ReturnType<typeof Ui.Switch.update>;

export type SwitchAttributes = Ui.Switch.SwitchAttributes;
export type ViewInputs = Ui.Switch.ViewInputs;

export const init = (config: InitConfig): InitReturn => [
  Ui.Switch.init(config),
  [],
];

export const { update } = Ui.Switch;
export const { setChecked } = Ui.Switch;
export const { reflectChecked } = Ui.Switch;
export const { view } = Ui.Switch;

export {
  switchButtonClassName,
  switchDescriptionClassName,
  switchKnob,
  switchLabelClassName,
  switchRowClassName,
  switchTextClassName,
} from "./view";

import clsx from "clsx";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

export const switchRowClassName = "flex items-center gap-3";

export const switchButtonClassName =
  "relative inline-flex h-6 w-11 shrink-0 items-center rounded-full bg-gray-300 transition-colors data-[checked]:bg-accent-600 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const switchLabelClassName =
  "text-sm font-medium leading-5 text-gray-900";

export const switchDescriptionClassName = "text-sm leading-5 text-gray-500";

export const switchTextClassName = "space-y-1";

export const switchKnob = (isChecked: boolean): Html => {
  const h = html();

  return h.span(
    [
      h.Class(
        clsx(
          "pointer-events-none inline-block h-4 w-4 rounded-full bg-white shadow transition-transform",
          isChecked ? "translate-x-6" : "translate-x-1"
        )
      ),
    ],
    []
  );
};

import { Match as M, Schema as S } from "effect";
import { Command, Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, test } from "vitest";

import * as Switch from "./index";

const GotSwitchMessage = m("GotSwitchMessage", {
  message: Switch.Message,
});

const Model = S.Struct({
  switchModel: Switch.Model,
});

type Model = typeof Model.Type;

const Message = S.Union([GotSwitchMessage]);
type Message = typeof Message.Type;

const initialModel: Model = {
  switchModel: Switch.init({ id: "notifications-switch" })[0],
};

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotSwitchMessage: ({ message }) => {
        const [switchModel, switchCommands] = Switch.update(
          model.switchModel,
          message
        );

        return [
          evo(model, { switchModel: () => switchModel }),
          Command.mapMessages(switchCommands, (message) =>
            GotSwitchMessage({ message })
          ),
        ];
      },
    })
  );

const view = (model: Model): Html => {
  const h = html<Message>();

  return h.submodel({
    slotId: model.switchModel.id,
    model: model.switchModel,
    view: Switch.view,
    viewInputs: {
      toView: (attributes) =>
        h.div(
          [h.Class(Switch.switchRowClassName)],
          [
            h.button(
              [...attributes.button, h.Class(Switch.switchButtonClassName)],
              [Switch.switchKnob(model.switchModel.isChecked)]
            ),
            h.div(
              [h.Class(Switch.switchTextClassName)],
              [
                h.label(
                  [...attributes.label, h.Class(Switch.switchLabelClassName)],
                  ["Enable notifications"]
                ),
                h.p(
                  [
                    ...attributes.description,
                    h.Class(Switch.switchDescriptionClassName),
                  ],
                  ["Get notified when something important happens."]
                ),
              ]
            ),
          ]
        ),
    },
    toParentMessage: (message) => GotSwitchMessage({ message }),
  });
};

const disabledView = (model: Model): Html => {
  const h = html<Message>();

  return h.submodel({
    slotId: "disabled-switch",
    model: model.switchModel,
    view: Switch.view,
    viewInputs: {
      isDisabled: true,
      toView: (attributes) =>
        h.div(
          [h.Class(Switch.switchRowClassName)],
          [
            h.button(
              [...attributes.button, h.Class(Switch.switchButtonClassName)],
              [Switch.switchKnob(false)]
            ),
            h.label(attributes.label, ["Locked notifications"]),
          ]
        ),
    },
    toParentMessage: (message) => GotSwitchMessage({ message }),
  });
};

describe("Switch registry view", () => {
  test("renders label, description, and toggles checked state", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(
        Scene.role("switch", { name: "Enable notifications" })
      ).toExist(),
      Scene.expect(
        Scene.text("Get notified when something important happens.")
      ).toExist(),
      Scene.expect(
        Scene.role("switch", { name: "Enable notifications" })
      ).not.toBeChecked(),
      Scene.click(Scene.role("switch", { name: "Enable notifications" })),
      Scene.expect(
        Scene.role("switch", { name: "Enable notifications" })
      ).toBeChecked()
    );
  });

  test("supports disabled switch state", () => {
    Scene.scene(
      { update, view: disabledView },
      Scene.with(initialModel),
      Scene.expect(
        Scene.role("switch", { name: "Locked notifications" })
      ).toBeDisabled()
    );
  });
});
